        plane.to_2d(Kernel::Point_3(polygon_coords[0][0], polygon_coords[0][1], polygon_coords[0][2])), 
        walk_start
    );
    Triangulation::Vertex_handle last_vh = triangulation.insert(
        plane.to_2d(Kernel::Point_3(polygon_coords[polygon_coords.size()-1][0], polygon_coords[polygon_coords.size()-1][1], polygon_coords[polygon_coords.size()-1][2])), 
        walk_start
    );
    if (first_vh != last_vh) {
        triangulation.odd_even_insert_constraint(last_vh, first_vh);
    }
}
